عبد الفتاح السيسى$m245$,'b19fbcbcdd36bb889506613855f86014',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(1,0,1,$m245$فى تطبيق أحكام هذا القانون والقرارات الصادرة تنفيذا له ، بقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منهما :
السجل : سجل إشهار الضمانات المنقولة المنشأ وفقا لأحكام هذا القانون .
المنقول : كل منقول مادى قائم أو مستقبلى أو منقول معنوى قائم مملوك للمدين أو مقدم الضمانا أو الدائن ، يكون ضمانا لالتزام أو دين أو تمويل أو تسهيل ائتمانى وفقا للضوابط التى تضعها اللائحة التنفيذية وعلى الأخص ما يلى :
1- الديون المستحقة أو المؤجلة .
2- الحسابات الدائنة لدى البنوك بما فى ذلك حساب الوديعة أو الحساب الجارى .
3- السندات القابلة لنقل ملكيتها عن طريق التسليم أو التظهير التى تثبت استحقاق مبلغ أو ملكية بضائع ، بما فى ذلك الأوراق التجارية وشهادات الإيداع البنكية ووثائق الشحن وسندات إيداع البضائع .
4- المعدات و أدوات العمل أو المخزون .
5- الأشجار أو المحاصيل الزراعية أو الحيوانات أو الطيور .
6- العقار بالتخصيص شريطة إمكانية فصله عن العقار دون إحداث ضرر لأى منهما .
7- المعادن قبل استخراجها .
8- الحقوق الواردة على الإبداعات والإبتكارات من براءات الاختراع والعلامات التجارية وحقوق مؤلف وغيرها من حقوق الملكية الفكرية .
المنقول المستقبلى : المنقول المادى المتوقع وجوده مستقبلا فى ملكية المدين أو مقدم الضمان طبقا للمجرى العادى للأمور .
الدائن : المضمون له من البنوك أو الجهات التى تمارس نشاط التمويل وغيرها من الجهات و الأشخاص المانحة للتمويل أو الائتمان وفقا لما تحدده اللائحة التنفيذية .
المدين : الشخص الطبيعى أو الاعتبارى الملتزم بالوفاء بالتزام أو دين مضمون .
مقدم الضمان : مالك المقول الضامن ، سواء المدين أو الغير .
حق الضمان : الحق العينى التبعى الذى يقع على المنقول الضامن بموجب عقد الضمان المبرم بين الدائن والمدين ومقدم الضمان كضمان للوفاء بالتزام أو دين .
عقد الضمان : العقد المبرم بين الدائن والمدين ومقدم الضمان والمثبت لحقوق الدائن على المنقول بالاسترشاد بالنموذج الذى تضعه الجهة الإدارية المختصة .$m245$,'a8266df7ec679133bc2fec541b79b3f8',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(2,0,1,$m245$تسرى الأحكام الواردة فى هذا القانون على الحقوق المضمونة بمنقول فى حيازة المدين أو مقدم الضمان يتفق أطراف عقد الضمان على شهره وفقا لأحكام هذا القانون ، بما فى ذلك :
1- الحقوق المترتبة على بيع المنقول المشروط تأجيل نقل ملكيته لحين استيفاء الثمن .
2- الحقوق المترتبة على بيع المنقول المشروط استرداده أو إعادة شرائه عند إخلال المدين بالوفاء بالتزاماته .
3- الحقوق المترتبة على استخدام أو الترخيص باستخدام حقوق الملكية الفكرية .
وتسرى أحكام هذا القانون المتعلقة بنفاذ حق الضمان تجاه الغير والأولوية والتنفيذ على المنقول الضامن على الحقوق التالية :
1- حق الدائن فى رهن الدين .
2- حق المؤجر فى التأجير التمويلى أو التشغيلى الذى تزيد مدته على ستة أشهر .
3- حق مالك البضاعة برسم البيع .
4- حق الدائن فى رهن المحل التجارى فى حال قيامه بشهره وفقا لأحكام هذا القانون .
ولا تسرى أحكام هذا القانون على الحقوق المترتبة على رهن الأوراق المالية وكذا الحقوق المترتبة على المنقول المستقبلى الناتج عن الميراث ، أو الوصية ، أو المعاشات ، أو وثائق التأمين على الحياة ، أو مستحقات التعويض ، أو النفقة ، أو الأجور ، أو الرواتب ، وذلك كله وفقا للقواعد التى تحددها اللائحة التنفيذية .
ويجوز للدائن المرتهن حيازيا شهر رهنه بالقيد فى السجل على ألا يخل ذلك بنفاذ الحق تجاه الغير وفق أحكام القانون المدنى ، وفى حال الشهر تسرى على هذا الرهن الأحكام المتعلقة بالأولوية والتنفيذ الواردة فى هذا القانون .$m245$,'93d19d99f625663a90580384f93a35bb',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(3,0,1,$m245$لا يجوز إنشاء حق ضمان على المنقولات الآتية :
1- المنقولات المملوكة للدولة أو لهيئات وجهات الوقف ، أو المملوكة للسفارات الأجنبية والهيئات التى تتمتع بالحصانة .
2- الإمتيازات والترخيص الممنوحة من الدولة ، أو الهيئات العامة ، أو أحد الأشخاص الاعتبارية العامة .
3- المنقولات التى تملكها البنوك عدا المعدات اللازمة لعملها لتمويل شرائها .
4- المنقولات المخصصة لأغراض شخصية ، أو منزلية إلا لتمويل شرائها .
5- المنقولات المملوكة على الشيوع ما لم يوافق جميع المالكين على إنشاء حق الضمان .$m245$,'6caad4949f413d97da46a60ad434fd3c',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(4,0,1,$m245$تقوم الجهة الإدارية المختصة بإنشاء سجل إلكترونى عام لشهر حقوق الضمان و أى تعديل أو شطب عليها ، وذلك تطبيقا لأحكام هذا القانون .
ويجوز للجهة الإدارية المختصة أن تعهد بإنشاء وتشغيل هذا السجل لإحدى الجهات أو الشركات المتخصصة تحت رقابتها ، وذلك وفقا للقواعد والضوابط التى تحددها اللائحة التنفيذية .
وفى جميع الأحوال ، تكون البيانات والمعلومات الموجودة بالسجل ملك للجهة الإدارية المختصة .$m245$,'39721056c497c0a2edfc92e474ddc628',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(5,0,1,$m245$تقوم الجهة القائمة بتشغيل السجل بإنشاء موقع إلكترونى على شبكة المعلومات الدولية ، يمكن من خلاله الإطلاع على البيانات المشهرة بالسجل بعد أداء مقابل الاطلاع الذى تحدده اللائحة التنفيذية ، بما لا يجاوز خمسمائة جنيه سنويا ، وذلك وفقا للمواصفات والضوابط التى تحددها الجهة الإدارية المختصة .
ويحظر بغير موافقة مسبقة من الجهة الإدارية المختصة إنشاء مواقع إلكترونية شبيهة بالموقع الإلكترونى المشار إليه بالفقرة السابقة ، أو قد يضلل الجمهور بأنه بتضمن البيانات ، أو المعلومات المشهرة بالسجل .
ويكون الحصول على صورة معتمدة من البيانات المشهرة فى السجل وفقا للضوابط وبعد أداء المقابل الذى تحدده اللائحة التنفيذية ، وبما لا يجاوز مائة جنيه .
وتكون للبيانات المشهرة بالسجل المتعلقة بوقت الإشهار وتاريخه والمصدق عليها من السجل حجية المحررات الرسمية فى الإثبات .$m245$,'5a13a1f7ff0a5d6d63b630feb821ed10',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(6,0,1,$m245$يتم شهر حق الضمان المقرر على المنقول بالقيد بالسجل من خلال قيام الدائن باستيفاء النموذج الإلكترونى المعد لهذا الغرض على أن يتضمن كافة المعلومات الأساسية التى يتضمنها عقد الضمان وعلى الاخص وصف المنقول الضامن وصفا عاما أو خاصا وبيان أطراف عقد عقد الضمان وصفاتهم بالنسبة لهذا المنقول الضامن ومدة الضمان .
وتحدد اللائحة التنفيذية إجراءات تعديل الشهر أو شطبه ، وكذلك مقابل الخدمات التى يقدمها السجل ، بما لا يجاوز خمسمائه جنيه .$m245$,'c2246cdb36548fa719608e18f3a289fc',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(7,0,1,$m245$بمراعاة حكم المادة (2) من هذا القانون يجب أن يكون المدين أو مقدم الضمان متمتعا بالأهلية ، وأن يكون له حق إنشاء حق الضمان على المنقول الضامن .
وإذا كان مقدم الضمان شخصا غيرالمدين كان له إلى جانب تمسكه بأوجه الدفع الخاصة به ، أن يتمسك بما للمدين التمسك به من أوجه الدفع المتعلقة بالدين ، ويبقى له هذا الحق ولو تنازل عنه المدين .$m245$,'db19f7a87aaeb870ec5e1c517bbf9a77',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(8,0,1,$m245$يشترط لإنشاء حق ضمان ونفاذه بين أطرافه ما بلى :
1- أن يبرم عقد ضمان بشكل مستند عرفى أو رسمى ، كما يجوز أن يكون بشكل محرر إلكترونى وفقا للقانون رقم 15 لسنة 2004 المشار إليه .
2- أن يكون مقدم الضمان مخولا بإنشاء حق الضمان على المنقول الضامن .
3- أن يلتزم الدائن بمنح التمويل المتفق عليه أو أداء المقابل لإنشاء حق الضمان .
ويجب أن تتضمن شروط عقد الضمان على الأقل ما يلى :
1- وصفا عاما أو خاصا للمنقول الضامن ، على أن يكون الوصف محددا ، إذا كانت الضمانة أشياء استعمالية مخصصة لأغراض شخصية أو منزلية .
2- مدة الضمان .
3- قبول المدين أو مقدم الضمان شهر حق الضمان .
ولأطراف عقد الضمان وضع الشروط التجارية التى يرونها مناسبة للتعاقد بما فى ذلك ما يلى :
1- التزام المدين أو الحائز بالقيام بجميع التدابير والإجراءات اللازمة للمحافظة على المنقول الضامن وصيانته أو رعايته .
2- التزام المدين باستعمال وصيانة وإصلاح المنقولات الضامنة ، بما يتفق مع الأغراض التى أعدت لها ووفقا للأصول الفنية المتعارف عليها والتعليمات المتعاقد عليها بشأن المواصفات الفنية الواجب مراعتها .
3- التزام المدين بإخطار الدائن بما يطرأ على المنقول الضامن من عوارض تمنع الانتفاع به كليا أو جزئيا .
4- مدى سلطة الدائن فى القيام بمتابعة التزام المدين باستخدام المنقول الضامن فى الغرض المخصص له وبالحفاظ عليه وصيانته .
5- أولوية بيع المنقولات الضامنة فى حالة عدم وفاء المدين بالتزاماته .
وتقوم الجهة الإدارية المختصة بإتاحة نموذج عقد ضمان استرشادى على موقعها الإلكترونى بدون مقابل .$m245$,'467c71fbc55386408763cc9ba8ab0f96',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(9,0,1,$m245$يجوز إنشاء أكثر من ضمان على منقول واحد ، كما يجوز أن يتضمن عقد الضمان أكثر من منقول ضامن أو مجموعة من المنقولات المتغيرة .$m245$,'04a1494b6179f5fe1451f7613c0980d6',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(10,0,1,$m245$يعتبر المنقول أمانة فى يد المدين أو مقدم الضمان بموجب عقد الضمان ، لحين انقضائه وعليه بذل عناية الرجل المعتاد فى الحفاظ عليه وصيانته بما يتناسب مع طبيعته .$m245$,'3f64051e243b84271873a1e0051519a9',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(11,0,1,$m245$يترتب على الشهر بالسجل وفقا لحكم المادة (6) من هذا القانون نفاذ حق الضمان فى مواجهة الغير .
ويجوز لكل ذى مصلحة الاعتراض لدى قاضى الأمور المستعجلة على ما يرد من شهر لحقوق الضمان بالسجل دون أن يؤثر هذا الاعتراض على نفاذ حق الضمان فى مواجهته أو مواجهة الغير$m245$,'ed40640f7883dfcaebf64e88b17edd89',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(12,0,1,$m245$يجوز للدائن أن يتنازل عن حق الضمان المشهر إلى شخص آخر ويسوى هذا التنازل فى حق الغير من تاريخ إشهاره بالسجل .
ولا يسرى هذا التنازل فى حق المدين ومقدم الضمان إلا من تاريخ إخطارهما به وفقا للطريقة المحددة فى عقد الضمان .
كما يجوز للدائن التنازل كتابة عن مرتبة الأولوية لحق الضمان المقرر له وفقا لأحكام هذا القانون فى حدود الدين المضمون بهذا الحق ، ويكون هذا التنازل نافذا فى مواجهة الغير من تاريخ إشهار هذا التنازل بالسجل .$m245$,'8975cb4d53e4332d3eca4d31c88b40e1',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(13,0,1,$m245$على الجهات التى يخولها القانون صلاحية تحصيل حقوق الدولة أو غيرها من الحقوق المقررة قانونا إشهار الأحكام أو القرارات التى ترتب حقوقا على المنقولات ، وذلك مع عدم الإخلال بتلك الجهات وبمراعاة حكم المادة (24) من هذا القانون .
كما يجب على المحكمة المختصة بناء على طلب كتابى من المحكوم لصالحه التصريح له بشهر الحقوق المترتبة على منقولات المدين فى الحالتين التاليتين :
1- صدور حكم وقتى نهائى بتوقيع حجز تحفظى على هذه المنقولات .
2- صدور حكم وقتى نهائى بالتنفيذ على هذه المنقولات .
كما تقوم المحكمة المختصة بإخطار السجل بأحكام الإفلاس لشهرها فى السجل كما يلتزم المصفى بإشهار قرار التصفية فى السجل .
وتعفى جميع عمليات الشهر المنصوص عليها فى هذه المادة من الرسوم المنصوص عليها فى هذا القانون .$m245$,'896d2c42d7edb71319d758d807f38a76',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(14,0,1,$m245$لا يجوز تعديل شروط أو مدة الإشهار أو شطبة إلا بمقتضى حكم نهائى أو بطلب من الدائن مرفقا به اتفاق الطرفين .
وفى حالة انقضاء حق الضمان قبل انتهاء مدة الشهر المحددة فى السجل يلتزم الدائن بإلغاء الإشهار خلال عشرة أيام على الأكثر من تاريخ الانقضاء ، ولا يسرى الإلغاء فى مواجهة أى دائن تم شهر حقوقه على ذات المنقول فى ذات العقد ما لم يوافق على الإلغاء ، وإذا لم يقم الدائن بإلغاء الإشهار خلال المدة المشار إليها يصدر قاضى الأمور المستعجلة أمرا بإلغاء القيد خلال يومى عمل على الأكثر من تاريخ تقديم الطلب ، ويكون الدائن مسئولا عنن تعويض المدين أو مقدم الضمان بحسب الأحوال عن الأضرار الفعلية التى لحقت بأى منهما .
وتكون مصروفات الإشهار وتجديده وتعديله على الدائن ما لم يتفق على خلاف ذلك ، ويعفى شطب الإشهار من أى رسوم أو مصروفات .$m245$,'c86e55d0d1285f2f65c83813e308e55b',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(15,0,1,$m245$إذا أصبح المنقول الضامن عقارا بالتخصيص يستمر نفاذ حق الضمان فى مواجهة الغير ، ويتقدم ذلك الحق على الحقوق العينية الأخرى الواقعة على العقار بشرط التأشير بتسجيل حق الضمان فى صحيفة العقار بالشهر العقارى إذا كان العقار مسجلا .
ويجوز إنشاء حق ضمان على العقار بالتخصيص وفقا لأحكام هذا القانون وتحدد مرتبة حق الضمان فى هذه الحالة من تاريخ شهره فى السجل وتسجيله فى صحيفة العقار قبل توثيق أى حقوق أخرى على العقار .$m245$,'194aa3141820143c6922a6c1eba1ec18',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(16,0,1,$m245$يستمر نفاذ حق الضمان تجاه الغير إذا لحق المنقول بمال آخر بشكل قابل للفصل .
وفى حالة إنشاء حق ضمان على منقولات مثلية فيستمر نفاذ حق الضمان إذا اختلطت تلك المنقولات بمثيلاتها ، وفى هذه الحالة تتساوى حقوق الضمان النافذة تجاه الغير على مجموعة المقولات المثلية فى المرتبة ويتحدد كل حق بنسبة دينه المضمون لإجمالى المنقولات المختلطة اعتبارا من تاريخ الاختلاط ، وفقا للضوابط التى تحددها اللائحة التنفيذية .
وفى حال حصول المدين على تمويل لشراء منقولات إضافية تشكيل جزءا من منقولات سبق إنشاء حقوق أخرى عليها ، يكون للممول شراء هذه المنقولات الإضافية أولوية فى استيفاء حقوقه منها بشرط شهرها فى السجل خلال مدة لا تجاوز ثلاثة أيام عمل من تاريخ حيازتها ، وفى جميع الأحوال يتم إخطار الدائنين الآخرين المشهرة حقوقهم على المنقولات ، وفقا للضوابط التى تحددها اللائحة التنفيذية .$m245$,'6b0bcee4cd3c7f5c8151d9942783866c',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(17,0,1,$m245$يجوز للمدين التصرف فى المنقول أو تأجيره بعد سداد الدين المضمون أو بالباقى منه بحسب الأحوال وبعد خصم مقابل تعجيل الوفاء المتفق عليه فى عقد الضمان ، وذلك وفقا للإجراءات التى تحددها اللائحة التنفيذية .
ويجوز للمدين بيع المنقول أو تأجيره إلى شخص آخر محملا بحق الضمان ويكون المدين الأصلى ضامنا للمشترى أو المستأجر فى تنفيذ التزاماته الناشئة عن عقد الضمان .
وللدائنين المشهرة حقوقهم المضمونة فى السجل أن يتتبعوا المنقول فى أية يد كانت ولهم أن يستوفوا حقوقهم قبل الدائنين العاديين بحسب مرتبة كل منهم .
وإذا تعدد حقوق الضمان على المنقول الضامن ، تحسب مرتبة حق الضمان من وقت وتاريخ إشهاره فى السجل بغض النظر عن التاريخ المنشئ للحق فى هذه الضمانات ، ويستوفى صاحب الحق الأسبق فى الإشهار حقه قبل الدائن الذى يليه .
ويجوز لمقدمى الضمان فى حال تعددهم تعيين وكيل عنهم يتولى مباشرة الحقوق المقررة لهم على منقولات المدين .
ولا يجوز للمدين أو الغير الاحتجاج على الدائن بأى حق يتعارض مع بيانات السجل المتعلقة بوقت الإشهار وتاريخه .
ومع ذلك يؤول المنقول لمشتريه أو لأى شخص أخر يكسب حقا عليه يكون خاليا من حق الضمان المشهر إذا وافق على ذلك جميع الدائنين المشهرة حقوقهم على المنقول ، أو إذا كان التصرف فى المنقول الضامن قد تم ضمن الأعمال المعتادة لمقدم الضمان .$m245$,'d69293663e41f3fafc3e5d291d75da38',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(18,0,1,$m245$يعتبر عقد الضمان شاملا للمقابل العينى أو النقدى الناتج عن بيع المال الضامن أو النتفاع به أو استبدال غيره به أو التعويض عن نقص قيمته أو تلفه ، كما يشمل ناتج ما يغله أو يدره المنقول أو ناتج استغلاله لسداد حقوق الدائن الواردة بعقد الضمان ما لم يتفق فى عقد الضمان على خلاف ذلك .
وفى حالة التأمين على المنقول أو هلاكه يكون للدائن على المبالغ الناشئة عن التأمين أو الحق الذى يترتب لمالك المنقول كالتعويض إذا تحقق سبب استحقاقها نفس الحقوق والامتيازات التى كانت له على المنقولات المؤمن عليها أو الهالكة .$m245$,'8342f063d046cff5507600fa919ad9c7',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(19,0,1,$m245$للدائن أن يطلب من قاضى الأمور المستعجلة بالمحكمة المختصة معاينة المنقول والعقار الذى يوجد فيه ومحل عمل مقدم الضمان ودفاتره وسجلاته أثناء نفاذ حق الضمان للتحقيق من عدم التصرف فى المنقول أو القيام بأى عمل من شانه الانتقاص من حقوق الدائن .
فإذا تبين من نتيجة المعاينة أنه قد تم التصرف فى المنقول أو ثبوت وجود إهمال جسيم فى صيانته أو العناية به طبقا لما ورد بعقد الضمان فلقاضى الأمور المسعجلة بناء على طلب الدائم إلزام المدين ومقدم المنقول بما يلى :
1- إصلاح المنقول الضامن وصيانته على نفقة مالك المنقول الضامن أو المدين خلال المدة المحددة بالإخطار .
2- تقديم تأمينات بديلة أو إضافية .
3- اعتبار أجل الدين حالا دون الحاجة للحصول على حكم قضائى .
ولا يحول اتخاذ الدائن للإجراءات السابقة دون ممارسة حقوق الأخرى الواردة فى عقد الضمان أو فى هذا القانون أو أى قانون آخر .$m245$,'866fd537c0d9e3aedb5281f464085a9d',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(20,0,1,$m245$فى حالة إشهار إفلاس المدين أو إعلان إعساره أو اتخاذ إجراءات التصفية ، لا تدخل المنقولات المشهرة فى السجل فى أموال التفليسة ولا فى الضمان العام للدائنين ، بشرط أن يكون هذه المنقولات مشهرة قبل البدء فى اتخاذ إجراءات الإفلاس أو الإعسار أو التصفية .
وفى الحالات المشار إليها بالفقرة السابقة يجب على الدائنين المشهرة حقوقهم وفقا لأحكام هذا القانون اتخاذ إجراءات بيع هذه المنقولات وفقا للطريقة المحددة بعقد الضمان واستيفاء حقوقهم المضمونة بهذه المنقولات وذلك خلال عام على الأكثر من تاريخ إشهار الإفلاس أو إعلان الإعسار أو اتخاذ إجراءات التصفية وبمراعاة مقابل تعجيل السداد المحدد بعقد الضمان ، وترد إلى مقدم الضمان أو المدين بحسب الأحوال أى فوائض من حصيلة بيع المنقولات تزيد على الوفاء بما مستحق لهؤلاء الدائنين .$m245$,'ae46a137722c836a28b3e190ecedf02a',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(21,0,1,$m245$للدائن أن يستوفى حقه من المنقول الضامن ، إذا تضمن عقد الضمان ذلك دون اتباع إجراءات التنفيذ الواردة بهذا القانون فى أى من الحالات الآتية :
1- إذا كان المنقول الضامن دينا لدى الغير فيتم تحصيله متضمنا نفقات التحصيل .
2- إذا كان المنقول الضامن سندات خطية قابلة للتحويل ، يتم تحصيل المبالغ أو تملك البضائع التى تمثلها تلك السندات .
3- إذا كان المنقول الضامن حساب وديعة أو حسابا جاريا أو أى حساب دائن آخر يتم إجراء المقاصة إذا كان الدائن بنكا يحتفظ بذلك الحساب ، وتتم المطالبة به إذا كان الحساب لدى بنك آخر .$m245$,'63503013e202eabb383d22cd00e22a29',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(22,0,1,$m245$إذا تضمن عقد الضمان أن يكون للدائن فى حالة عدم قيام المدين بتنفيذ التزاماته أو بسداد الدين المضمون أو الأقساط فى المواعيد ووفقا للشروط المتفق عليها فى العقد أن يبيع المنقول ، فلا يجوز للدائن البدء فى إجراءات البيع إلا بعد مضى خمسة أيام من تكليف المدين بالوفاء بموجب كتاب مسجل مصحوب بعلم الوصول ، وكذلك إخطار الدائنين المشهرة حقوقهم المضمونة على المنقول بذلك وفقا للضوابط والإجراءات التى تحددها اللائحة التنفيذية .
وفى حال إذا لم يتضمن عقد الضمان ذلك ، كان للدائن بعد انقضاء خمسة أيام من تاريخ تكليف المدين بالوفاء أن يطلب بعريضة تقدم إلى القاضى المختص بالمحكمة التى يقع فى دائرتها موطن المدين الآمر ببيع المنقول كله أو بعضه ، ولا يجوز تنفيذ الآمر الصادر من القاضى ببيع المنقول الضامن إلا بعد انقضاء خمسة أيام من تاريخ إخطاره إلى المدين ، وإخطار الدائنين المشهرة حقوقهم المضمونة مع بيان المكان الذى يجرى فيه البيع وتاريخه ساعته ، ويجرى البيع فى الزمان والمكان اللذين عينهما القاضى وبالطريقة التى يحددها بما يتناسب مع طبيعة المنقول الضامن .
ويجوز للدائن بيع المنقول دون اتباع الإجراءات والمدد الواردة بالفقرتين السابقتين فى حالة عدم وجود حقوق مضمونة لدائنين آخرين على ذات المنقول وموافقة المدين على البيع ، على أن يبذل فى ذلك العناية التى يبذلها فى أعماله الخاصة ، وكذلك فى الحالات الأخرى التى تحددها اللائحة التنفيذية وفقا للضوابط التى تضعها فى هذا الشأن .
ويترتب على بيع المنقول الضامن فى هذه الحالة تطهير المنقول من كافة الديون وتنتقل حقوق الدائنين إلى الثمن .
وفى جميع الأحوال لا يجوز أن يشمل البيع إلا ما يكفى للوفاء بحقوق الدائن ومصاريف البيع .
وتحدد اللائحة التنفيذية إجراءات إيداع حصيلة البيع خزينة المحكمة المختصة وإعداد قائمة بترتيب الدائنين المستحقين ومواعيد وأولوية توزيع حصيلة البيع .$m245$,'af8b21047c00ea21407e62ce10dda9bc',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(23,0,1,$m245$يكون الدائن مسئولا عن تعويض مقدم الضمان والمدين وأى من أصحاب الحقوق الأخرى على المال الضامن بحسب الأحوال عن الأضرار الناتجة عن مخالفته لإجراءات التنفيذ المنصوص عليها فى هذا القانون ولائحته التنفيذية .
وتسقط دعوى المسئولية عن تعويض الضرر بمضى سته أشهر من تاريخ حصول الواقعة المنشأة لها أو من تاريخ عمله بها ، أى التاريخين لاحق ، وذلك مالك يكن الفعل المنسوب يشكل جناية أو جنحة وفقا لهذا القانون أو أى قانون آخر فلا تسقط دعوى المسئولية إلا بسقوط الدعوى الجنائية .$m245$,'80240f3a03669c48a1ca1de48a7bbeb0',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(24,0,1,$m245$يكون لأصحاب حقوق الضمان المشهرة وفقا لأحكام هذا القانون امتياز على المنقول الضامن يسبق جميع حقوق الامتياز والرهن المقررة فى القوانين الأخرى عدا المصروفات القضائية ورسوم ونفقات التنفيذ على المنقول ، وذلك بمراعاة حقوق الدائنين المرتهن حيازيا وفقا لأحكام القانون المدنى .$m245$,'7c7640d1b74794f1ef9ecef2602fd2c3',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(25,0,1,$m245$إذا كانت حصيلة بيع المنقول الضامن والعوائد الناتجة عنه المنصوص عليها بالمادة (18) من هذا القانون لاتكفى للوفاء بالتزامات وحقوق الدائنين المشهرة بالسجل فتوزع وفق الترتيب التالى :
1- نفقات إصلاح المنقول وصيانته وإعداده للبيع .
2- رسوم ونفقات التنفيذ على المنقول .
3- سداد مستحقات أصحاب حقوق الضمان المشهرة على المنقول حسب أولويتها وفقا لأحكام هذا القانون .
4- سداد مستحقات أصحاب حقوق الامتياز وغيرها من الحقوق المقررة وفقا لأولويتها طبقا للقوانين المنظمة لها .
وفى حالة عدم كفاية حصيلة بيع المنقول الضامن للوفاء بحقوق الدائنين أو بعضهم ، فيكون لكل دائن مطالبة المدين بالباقى من قيمة الدين وعوائده وفقا للقواعد العامة فى استئداء الديون .
وترد للمدين أو مقدم الضمان بحسب الأحوال أى فوائض من حصيلة بيع المنقول تزيد على الوفاء بما ورد بالفقرة السابقة .$m245$,'fca5f69a5396c543b62911eeaf206d3f',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(26,0,1,$m245$يكون لقاضى التنفيذ بالمحكمة المختصة بناء على طلب من المدين أو مقدم الضمان أو أى من أصحاب الحقوق الأخرى على المنقول ، أن يقرر وقف إجراءات التنفيذ على المنقول وبيعه فى أية مرحلة من مراحل التنفيذ ولمرة واحدة إذا رأى أن نتائج التنفيذ قد يتعذر تداركها .
وفى هذه الحالة يجب على القاضى لقبول طلب التنفيذ أن يلزم مقدمه بتقديم تأمين نقدى أو كفالة مصرفية بمبلغ لا يقل عن قيمة المنقول أو مجموع قيم الديون والإلتزامات المضمون بها أيهما أقل ، لضمان ما قد يلحق بالمنقول من نقص أو ضرر .
ولقاضى التنفيذ بناء على طلب المدين أو مقدم الضمان أو أى من أصحاب الحقوق الأخرى على المنقول الضامن أن يعدل إجراءات التنفيذ فى أية مرحلة من مراحله بالشكل الذى يراه مناسبا ، إذا تبين له وجود مخالفة لإجراءات التنفيذ على المنقول الضامن والمنصوص عليها فى هذا القانون ولائحته التنفيذية .$m245$,'d720d9ec829e3a6c5168287f1feb1213',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(27,0,1,$m245$يكون للمدين أو مقدم الضمان لصالح المدين أو أى من أصحاب الحقوق الأخرى على المنقول أن يتقدم بطلب لقاضى الأمور المستعجلة بالمحكمة المختصة لإيقاف إجراءات البيع قبل يوم عمل على الأقل من التاريخ المحدد لبيع المنقول ، على أن يرفق بالطلب ما يفيد إيداع خزينة المحكمة ما يكفى لسداد حقوق الدائنين المشهرة بالسجل أو المتبقى منها بحسب الأحوال بالإضافة إلى جميع المصاريف والنفقات .
ويترتب على قبول الطلب وقف إجراءات البيع ، ويتم سداد حقوق الدائنين بحسب ترتيبها ، وكذلك مصاريف ونفقات التنفيذ من المبالغ المودعة خزينة المحكمة .$m245$,'8061efc75fdb4a36ecc5ef655ff480f9',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(28,0,1,$m245$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر ، يعاقب بالحبس وبغرامة تعادل قيمة الدين المضمون ، بما لا يقل عن ألف جنيه أو بإحدى هاتين العقوبتين ، كل من قام بتغيير معالم المنقول الضامن أو أوصافه المشهرة بالسجل أو طمس بياناته بقصد الإضرار بالدائن .
كما يعاقب بالغرامة المنصوص عليها بالفقرة السابقة المدين الذى يخالف التزاماته الواردة بالمادة (10) من هذا القانون ، وكذا المصفى الذى يخالف التزاماته الواردة بالمادة (13) من هذا القانون .$m245$,'056e1eee240a72157817cf5f0214bd08',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(29,0,1,$m245$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر ، يعاقب بالحبس مدة لا تقل عن ثلاث أشهر وبغرامة تعادل قيمة الدين المضمون ، بما لا يقل عن خمسين ألف جنيه أو بإحدى هاتين العقوبتين :
1- كل مدين بدل أو أتلف عمدا المنقول الضامن المشهر بالسجل أو تصرف فيه بالمخالفة لأحكامه .
2- كل دائن تعمد شهر حق ضمان بشكل مخالف للواقع أو لأحكام هذا القانون والقرارات الصادرة تنفيذا له .
ويعاقب بالغرامة المنصوص عليها بالفقرة السابقة كل من عرقل إجراءات التنفيذ على المنقول بقصد الإضرار بالدائنين .$m245$,'f87951ed4bc98b02e93f383d3d2623c1',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(30,0,1,$m245$يعاقب بالحبس مدة لا تقل عن سنة وبغرامة لا تقل عن مليونى جنيه أو بإحدى هاتين العقوبتين كل من أنشأ أو اشترك فى إنشاء موقع إلكترونى بالمخالفة لحكم المادة (5) من هذا القانون .$m245$,'9d61825cf88f5cdbab3fd2705c7c9c1e',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$),
(31,0,1,$m245$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى بذات العقوبات المقررة عن الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون ، إذا ارتكبت الجريمة باسم ولحساب الشخص الاعتبارى ، وثبت علمه بها واتجهت إرادته لارتكابها ، ويكون الشخص الاعتبارى مسئولا بالتضامن عن الوفاء بما يحكم به من عقوبات مالية وتعويضات .$m245$,'1100274d1333eb76af47d3b314f47b5c',DATE '2016-02-16',NULL,'active',NULL,NULL,$m245$النص كما ورد بالمصدر (طبعة منقولة من قاعدة بيانات تشريعات، غير الجريدة الرسمية) وفيه هفوات طباعة أصلية محفوظة كما طُبعت. تاريخ العمل محسوب: المادة 5 إصدار تجعل العمل من اليوم التالى لمرور ثلاثة أشهر من النشر، وبافتراض أن تاريخ النشر هو 15/11/2015 المذكور فى عنوان المصدر فيكون 2016-02-16؛ يُراجع بشرياً على الجريدة الرسمية. لا تعديل مذكور بالمصدر.$m245$);

DO $m245$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m245_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m245_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[245] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m245_art) <> 37 OR (SELECT sum(char_length(body)) FROM m245_art) <> 22647 OR (SELECT count(*) FROM m245_ver) <> 37 THEN
    RAISE EXCEPTION '[245] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=115 AND law_year=2015 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الضمانات المنقولة%' THEN
    RAISE EXCEPTION '[245] يوجد مستند آخر برقم 115 لسنة 2015 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, country_code, kind, governance_scope)
    VALUES (115, 2015, $t245$قرار رئيس الجمهورية بقانون رقم 115 لسنة 2015 بشأن تنظيم الضمانات المنقولة$t245$, $t245$قانون تنظيم الضمانات المنقولة$t245$, 'other', 'in_force', NULL, DATE '2015-11-14', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m245_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m245_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m245_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 37 THEN
    RAISE EXCEPTION '[245] عدد صفوف النص % بدل 37', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 37 THEN
    RAISE EXCEPTION '[245] عدد نسخ النص % بدل 37', v_vcnt;
  END IF;
  RAISE NOTICE '[245] قانون 115/2015: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m245$;
